const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s).toLocaleString([], {dateStyle:'medium',timeStyle:'short'}):'—';
const money=n=>'$'+Number(n||0).toFixed(2);
const safeLink=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)?esc(u.href):'#';}catch{return '#';}};
const pill=s=>`<span class="pill">${esc(s)}</span>`;
const labels={preparing:'Preparing email',pending:'Pending send',attention:'Needs attention',scheduled:'Scheduled',sending:'Sending',sent:'Sent',replied:'Replied',failed:'Send failed',check_sent:'Check delivery',stopped:'Stopped',not_sent:'Not sent'};
const groupLabels={all:'All prospects',pending:'Pending send',sent:'Emails sent',contacted:'Businesses contacted',followup:'Follow-up due',replied:'Businesses that replied',attention:'Needs attention'};
let data=null,view='prospects',filter='',statusFilter='all',dashboardGroup='sent',modalDraft=null,detailData=null;
let locationSelection=null,workspaceUnavailable=false,snapshotMode=null,lastSavedRefresh=0;
let notificationData={items:[],unread:0},notificationUnavailable=false;
let products=[],selectedProduct=new URLSearchParams(location.search).get('product')||sessionStorage.getItem('relay-product')||'',productDetailData=null;
let loadRequest=0;
let pageData={rows:[],counts:{},total:0,offset:0,hasMore:false},pageRequest=0,searchTimer;
const title=(heading,sub='',buttons='')=>`<div class="page-head"><div><h1>${heading}</h1>${sub?`<p>${sub}</p>`:''}</div><div class="actions">${buttons}</div></div>`;
const empty=(heading,sub)=>`<div class="empty"><h3>${heading}</h3><p>${sub}</p></div>`;
const input=(name,label,value,type='text',extra='')=>`<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const customerTypeOptions={b2b:'B2B businesses',b2c:'B2C market / distribution partners',individuals:'Individual professionals / creators',agencies:'Agencies',startups:'Startups',other:'Other / describe below'};
function customerFields(s={}){return `<fieldset><legend>Customer types</legend><div class="form-grid">${Object.entries(customerTypeOptions).map(([key,label])=>`<label class="checkbox"><input type="checkbox" name="customerTypes" value="${key}" ${(s.customerTypes||[]).includes(key)?'checked':''}>${label}</label>`).join('')}</div></fieldset><label>Describe your ideal customer<textarea name="customerDescription" rows="3" maxlength="8000" placeholder="For example: small video editing agencies, independent creators, or startups building consumer budgeting products">${esc(s.customerDescription||'')}</textarea></label><label>Additional customer targeting comments<textarea name="customerComments" rows="3" maxlength="8000" placeholder="Relevant workflows, company size, exclusions and what makes a prospect suitable">${esc(s.customerComments||'')}</textarea></label><p class="quiet">OpenAI uses these details for targeting and email personalization. Discovery uses public organizations and professional contacts; it does not profile private people by health conditions, addiction or financial vulnerability.</p>`;}
const draftMessage=d=>d.body.trim()+(d.artifact?.trim()?'\n\nFree sample\n-----------\n'+d.artifact.trim():'');
const prospectIssues=d=>(d.sendIssues||[]).filter(x=>!x.includes('postal address'));
function emailCheck(l){return !l.email?'Email not found':l.contact_status==='publicly_sourced'?'Public email sourced (delivery unknown)':l.verification==='valid'?'Previously checked address':l.verification==='invalid'?'Invalid email':l.verification==='risky'?'Mailbox unconfirmed':l.verification==='unverified'?'Email check pending':'Recipient reviewed';}
function sendingNotice(){if(data.settings.prospectingPaused)return '<div class="note warning">Prospecting is paused in this workspace, including research, drafting and sending. Product setup remains available.</div>';if(data.settings.outreachPaused)return '<div class="note warning">Outreach is paused. Use Resume Relay at the top before sending.</div>';return !data.settings.businessAddress.trim()?'<div class="note warning">Sending is paused. Add your postal address in <button class="text-button" data-go="settings">Settings</button>.</div>':!data.connections.sendingEnabled?'<div class="note warning">Sending is paused. Your address is saved; sending still needs activation in Settings.</div>':'';}
function currentProduct(){return products.find(p=>p.id===selectedProduct);}
function profileReady(p=currentProduct()){return !!p&&p.state==='approved'&&p.enabled===1&&p.approved_revision===p.revision;}
function workspaceNotice(){
 if(snapshotMode)return backupNotice();
 const s=data.settings,p=data.pipeline||{},product=currentProduct(),items=[];
 const add=(text,action,label)=>items.push({text,action,label});
 const pending=!!selectedProduct&&!profileReady(product);
 if(s.outreachPaused)add('Relay is paused. Resume Relay at the top to allow product analysis or prospect work.');
 if(pending){
  if(product?.state==='target_review')add('Review and approve the target profile in Products, then choose Resume prospects. Product setup remains available.','products','Review target profile');
  else if(product?.state==='analyzing')add('Product analysis is in progress. Review its target profile when ready; prospecting remains paused.','products','View product analysis');
  else if(product?.error)add('Product analysis needs attention: '+product.error,'products','Review product');
  else if(product?.enabled===0)add('This product is disabled. Enable it before resuming prospecting.');
  else add('Analyze this product and approve its target profile before finding prospects.','products','Review product');
 }else if(s.prospectingPaused)add('Prospecting is paused for this workspace. Resume prospects when ready; product setup and target-profile analysis remain available.');
 else if(s.discoveryPaused)add('Automatic prospect searches are paused. Find prospects can request a manual search.');
 else if(Date.parse(s.discoveryPausedUntil||'')>Date.now())add('Automatic prospect searches are paused until '+date(s.discoveryPausedUntil)+'. Find prospects overrides this wait.');
 const running=!s.outreachPaused&&!s.prospectingPaused&&!pending;
 if(running){
  if(!data.connections.automationEnabled)add('Automatic research is not activated for Relay.','settings','Open Settings');
  else if(s.researchAutomation===false)add('Automatic discovery and research are turned off for this workspace.','settings','Open Settings');
  else if(p.waitingResearch>=s.dailyNewLimit*3)add('New searches wait while '+p.waitingResearch+' businesses await research.');
 }
 if(p.providerBlock)add('OpenAI stopped requests for a billing problem. Update the connected project billing, then confirm in Settings.','settings','View billing status');
 else if(p.pausedJobs)add(p.pausedJobs+' tasks are paused. Review the recorded reasons in Settings, Activity & costs.','settings','Review paused tasks');
 if(p.attentionJobs)add(p.attentionJobs+' tasks need review in Settings, Activity & costs.','settings','Review tasks');
 const emailsReady=Number(pageData.counts.pending||0)+Number(data.metrics?.scheduled||0)>0;
 if(running&&emailsReady&&view!=='products'){
  if(!s.businessAddress.trim())add('Add your postal address in Settings before sending emails. Research can continue.','settings','Add sender details');
  else if(!data.connections.sendingEnabled)add('Email sending is not activated. Research can continue.','settings','Review sending');
 }
 return items.length?'<section class="note warning workspace-notice" role="status" aria-label="Workspace notices"><strong>Workspace status and next steps</strong><ul>'+items.map(i=>'<li>'+esc(i.text)+(i.action&&view!==i.action?' <button class="text-button" data-go="'+i.action+'">'+esc(i.label)+'</button>':'')+'</li>').join('')+'</ul></section>':'';
}

async function api(path,payload){if(snapshotMode&&payload!==undefined&&!['/api/login','/api/logout'].includes(path))throw new Error('Saved records are read only while the database is unavailable.');if(selectedProduct&&!/^\/api\/(products|notifications|outreach|openai|session|login|logout)(?:[/?]|$)/.test(path))path+=(path.includes('?')?'&':'?')+'product='+encodeURIComponent(selectedProduct);const r=await fetch(path,{method:payload===undefined?'GET':'POST',headers:{'Content-Type':'application/json','X-Requested-With':'Prepyr'},...(payload===undefined?{}:{body:JSON.stringify(payload)})});const value=await r.json();if(value.availability?.readOnly)snapshotMode=value.availability;if(r.status===401){$('#app').hidden=true;$('#login').hidden=false;}if(!r.ok){const error=new Error(value.error||'Request failed');error.code=value.code;error.status=r.status;throw error;}return value;}
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').hidden=true,7000);}
async function refreshNotifications(){try{const feed=await api('/api/notifications');notificationData={items:feed.items||[],unread:feed.unread||0};notificationUnavailable=false;}catch{notificationUnavailable=true;}renderNotifications();}
function positionNotifications(){const panel=$('#notification-panel');if(panel&&!panel.hidden){const bottom=$('#notification-toggle').getBoundingClientRect().bottom;panel.style.setProperty('--notification-top',Math.max(8,bottom+8)+'px');$('#notification-list').style.maxHeight=Math.min(520,Math.max(120,window.innerHeight-bottom-90))+'px';}}
window.addEventListener('resize',positionNotifications);
function renderNotifications(){const badge=$('#notification-count');if(!badge)return;badge.hidden=!notificationData.unread;badge.textContent=notificationData.unread>99?'99+':String(notificationData.unread);$('#notification-toggle').setAttribute('aria-label',`Notifications, ${notificationData.unread} unread`);$('#notifications-read-all').disabled=notificationUnavailable||!!snapshotMode||!notificationData.unread;positionNotifications();$('#notification-list').innerHTML=notificationUnavailable?'<p class="notification-empty">Notifications are temporarily unavailable. Try refreshing.</p>':notificationData.items.length?notificationData.items.map(n=>`<button class="notification-item ${n.read_at?'':'unread'}" data-notification="${esc(n.id)}"><strong>${esc(n.title)}</strong><span>${esc(n.body)}</span><small>${esc(n.workspace_name)} · ${date(n.created_at)}${n.read_at?'':' · Unread'}</small></button>`).join(''):'<p class="notification-empty">No notifications yet. Replies, bounces and follow-up drafts will appear here.</p>';}
document.addEventListener('click',e=>{if(!e.target.closest('.notification-center')&&$('#notification-panel')){$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#notification-panel')&&!$('#notification-panel').hidden){$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');$('#notification-toggle').focus();}});
async function fetchPage(offset=0){const seq=++pageRequest;const group=view==='dashboard'?dashboardGroup:statusFilter;const result=await api('/api/prospects?'+new URLSearchParams({group,q:filter,offset:String(offset)}));if(seq!==pageRequest)return false;pageData=result;return true;}
async function load(){
 const seq=++loadRequest;
 await api('/api/session');if(seq!==loadRequest)return;
 await refreshNotifications();if(seq!==loadRequest)return;
 $('#login').hidden=true;$('#app').hidden=false;
 const list=await api('/api/products').catch(()=>({products:[]}));if(seq!==loadRequest)return;products=list.products||[];if(selectedProduct&&!products.some(p=>p.id===selectedProduct)){selectedProduct='';sessionStorage.removeItem('relay-product');}
 if(view==='products'&&selectedProduct){const detail=await api('/api/products/'+selectedProduct);if(seq!==loadRequest)return;productDetailData=detail;}
 try{const next=await api('/api/dashboard?summary=1');if(seq!==loadRequest)return;snapshotMode=next.availability?.readOnly?next.availability:null;if(snapshotMode)lastSavedRefresh=Date.now();await fetchPage(pageData.offset);if(seq!==loadRequest)return;data=next;workspaceUnavailable=false;render();}
 catch(error){if(seq!==loadRequest)return;if(error.status===401)throw error;workspaceUnavailable=true;data=null;pageData={rows:[],counts:{},total:0,offset:0,hasMore:false};if($('#modal').open)$('#modal').close();$('#breadcrumb').textContent='Workspace';$('#pace').textContent='Signed in';$('#live-status').textContent='Data unavailable';$('#content').innerHTML=empty('Workspace data is temporarily unavailable',esc(error.message))+'<button data-reload>Try again</button>';}
}
async function action(path,payload={},message='Saved'){const result=await api(path,payload);toast(result.message||message);await load();return result;}
function rowStatus(row){if(row.email_status==='preparing'){if(row.research_job_state==='paused_provider')return /credit_balance_exhausted|insufficient_quota|billing_hard_limit_reached/.test(row.research_job_error||'')?'OpenAI credits exhausted':'Provider needs attention';if(row.research_job_state==='failed')return 'Research needs attention';if(row.research_job_state==='uncertain')return 'Research outcome needs review';if(data.settings.outreachPaused||data.settings.prospectingPaused)return 'Research paused';if(row.research_job_state==='paused')return /Daily/.test(row.research_job_error||'')?'Daily research limit reached':'Research paused';if(row.research_job_state==='pending')return 'Research queued';}if(row.inbound_classification==='bounce')return 'Bounced';if(row.inbound_classification==='optout')return 'Unsubscribed';if(row.inbound_classification==='automatic')return 'Automatic reply received';if(row.inbound_classification==='reply')return row.email_status==='attention'?'Reply received ? Needs attention':'Reply received';const stages={contact_search:'Finding public contact',contact_extract:'Reviewing public contact',business_research:'Researching business',business_research_refine:'Deepening research',solution_design:'Designing solution',draft_generate:'Writing email',draft_assess:'Checking personalization'};return row.email_status==='preparing'?(stages[row.research_stage]||'Research queued'):labels[row.email_status]||'Preparing email';}
function prospectTable(rows,emails=false){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Prospect</th><th>Email</th><th>Status</th><th>${emails?'Sent at':'Last sent'}</th><th>Follow-up</th><th></th></tr></thead><tbody>${rows.map(l=>`<tr><td><strong>${esc(l.company)}</strong><small>${esc([l.city,l.country].filter(Boolean).join(', '))}</small>${emails?`<small>${esc(l.draft_subject)}</small>`:''}</td><td class="email-cell">${esc(l.email||'Not found')}</td><td><span class="pill status-${esc(l.email_status)}">${esc(rowStatus(l))}</span>${l.draft_kind==='reply'&&l.email_status==='pending'?'<small>Your reply is ready</small>':''}${l.draft_kind==='followup'&&l.email_status==='pending'?'<small>Follow-up email ready</small>':''}</td><td>${date(emails?l.sent_at:l.last_sent_at)}</td><td>${l.last_inbound_at?'Stopped after reply':l.status==='contacted'&&l.next_followup_at?date(l.next_followup_at):'—'}${l.followup_count?`<small>${l.followup_count} of 3 follow-ups sent</small>`:''}${l.draft_kind==='followup'&&l.draft_status!=='sent'?'<small>Follow-up '+(Number(l.followup_count||0)+1)+' ready for review</small>':''}</td><td><button data-open="${esc(l.id)}" ${l.draft_id?`data-email="${esc(l.draft_id)}"`:''}>${l.draft_kind==='followup'&&['pending','approved','failed'].includes(l.draft_status)?'Open Follow Up':l.draft_kind==='reply'&&['pending','approved','failed'].includes(l.draft_status)?'Open Reply':l.draft_id?'Open email':'Open prospect'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No ready emails yet.','Qualified prospects appear here once research and email drafting are complete. Unfinished and rejected candidates stay out of this list.');}
function pagination(){return `<div class="pagination"><span>${pageData.total?`${pageData.offset+1}–${pageData.offset+pageData.rows.length} of ${pageData.total}`:'0 results'}</span><button data-page="${Math.max(0,pageData.offset-50)}" ${pageData.offset?'':'disabled'}>Previous</button><button data-page="${pageData.offset+50}" ${pageData.hasMore?'':'disabled'}>Next</button></div>`;}
function prospects(){return title('Prospects','Only qualified businesses with complete, researched emails appear here.', '')+`<p class="quiet">${Number(data.metrics?.campaign?.qualified??data.metrics?.draftedToday??0)} / ${Math.min(data.settings.dailyNewLimit,data.settings.dailyLeadLimit)} qualified emails ${selectedProduct?'in this campaign':'prepared today'}. Only complete drafts count. Research continues within your saved daily and monthly limits.</p><div class="location-toolbar">${locationPicker()}<button data-discovery-control ${data.settings.outreachPaused?'disabled':''}>${data.settings.prospectingPaused||data.settings.discoveryPaused?'Resume prospects':'Pause prospects'}</button><span class="discovery-status">${data.settings.prospectingPaused||data.settings.discoveryPaused?'Prospecting paused':'Prospecting enabled'} - ${selectedProduct?'new campaigns after a '+data.settings.discoveryIntervalDays+'-day gap; Find prospects overrides this wait':'every '+data.settings.discoveryIntervalDays+' days'}</span><button class="primary" data-action="discover" title="Start a manual search without the automatic campaign wait">Find prospects</button></div>`+`<div class="filter-bar"><input id="search" type="search" placeholder="Search business, email or location" value="${esc(filter)}"><select id="status-filter" aria-label="Filter prospects">${Object.entries(groupLabels).filter(([key])=>!['sent','attention'].includes(key)).map(([key,label])=>`<option value="${key}" ${key===statusFilter?'selected':''}>${label}</option>`).join('')}</select></div>`+prospectTable(pageData.rows)+pagination();}
function dashboard(){const c=pageData.counts||{};return title('Dashboard','Click a number to see the details below.')+`<div class="dashboard-cards">${['pending','sent','contacted','followup','replied'].map(key=>`<button class="metric ${dashboardGroup===key?'selected':''}" data-group="${key}" aria-pressed="${dashboardGroup===key}"><span>${groupLabels[key]}</span><strong>${Number(c[key]||0)}</strong></button>`).join('')}</div><section class="dashboard-details"><h2>${groupLabels[dashboardGroup]}</h2>${prospectTable(pageData.rows,dashboardGroup==='sent')}${pagination()}</section>`;}
function budgetHtml(){const b=data.budgets.find(b=>b.provider==='openai')||{};return `<div class="connection"><strong>OpenAI — all discovery and research</strong><span>${money(b.committed)} / ${money(data.settings.openaiBudget)}</span></div><p class="quiet">Includes searches, contacts, research, drafts and replies. Delivery is unknown until a mailbox responds.</p>`;}
function chosenLocations(){return [...document.querySelectorAll('[name="locationIds"]:checked')].map(x=>x.value);}
function locationPicker(){const selected=locationSelection||data.settings.locationIds||['worldwide'],options=data.locationOptions||[{id:'worldwide',label:'Worldwide - automatic',group:'Automatic'}];return '<details class="location-picker"><summary><span id="location-summary">'+(selected.includes('worldwide')?'Worldwide - automatic':selected.length+' locations selected')+'</span></summary><div class="location-menu"><input id="location-search" type="search" placeholder="Find a country, region or city" aria-label="Filter locations"><div class="location-options">'+[...new Set(options.map(x=>x.group))].map(group=>'<div class="location-group"><strong>'+esc(group)+'</strong>'+options.filter(x=>x.group===group).map(o=>'<label class="checkbox location-option" data-location-label="'+esc(o.label.toLowerCase())+'"><input type="checkbox" name="locationIds" value="'+esc(o.id)+'" '+(selected.includes(o.id)?'checked':'')+'>'+esc(o.label)+'</label>').join('')+'</div>').join('')+'</div></div></details>';}
async function saveLocations(){const ids=chosenLocations();if(!ids.length)throw new Error('Select at least one location.');const r=await api('/api/settings/locations',{locationIds:ids});if(r.settings)data.settings=r.settings;locationSelection=null;return r;}

function activity(){return `<details class="panel"><summary>Activity & costs</summary><div class="spaced">${budgetHtml()}</div><div class="actions spaced">${data.pipeline?.providerBlock?'<button data-billing-updated>I updated OpenAI billing</button>':''}<button data-action="tick">Run background tasks</button><a href="/api/export${selectedProduct?'?product='+encodeURIComponent(selectedProduct):''}" download>Export records</a></div><details><summary>Task history</summary>${data.jobs.map(j=>`<div class="list-row"><div><strong>${esc(j.company||'Prospect search')}</strong><small>${esc(j.kind)} · ${esc(j.error||date(j.created_at))}</small></div><div>${pill(j.state)}${['failed','paused_provider'].includes(j.state)?`<button data-retry="${j.id}">Retry</button>`:''}</div></div>`).join('')||'<p>No tasks yet.</p>'}</details><details><summary>Search history</summary>${data.runs.map(r=>{const c=JSON.parse(r.campaign);return `<div class="list-row"><div>${esc(c.query)} · ${esc(c.location)}<small>${r.imported||0} businesses · ${r.held||0} need review · ${esc(r.error||date(r.created_at))}</small></div>${pill(r.state)}</div>`;}).join('')||'<p>No searches yet.</p>'}</details><details><summary>Event log</summary>${data.events.map(e=>`<p><small>${date(e.created_at)}</small><br>${esc(e.detail)}</p>`).join('')}</details></details>`;}
function settingsPage(){const s=data.settings,c=data.connections;const numberFields=[['dailyLeadLimit','Qualified prospects per day (maximum)',20],['dailyNewLimit','Qualified email target / daily send cap',selectedProduct?12:20],['dailyTotalLimit','Total emails per day',selectedProduct?12:100],['dailyResearchLimit','Prospects researched per day',selectedProduct?20:100],['followupDays','Follow-up days'],['sendStartHour','Sending starts (recipient hour)',23],['sendEndHour','Sending ends (recipient hour)',24]];return title('Settings','Changes apply only to '+esc(products.find(p=>p.id===selectedProduct)?.name||'Existing outreach')+'. Service connections are shared.')+`<form id="sender-form" class="panel"><h2>Sender details</h2><div class="form-grid">${input('senderName','Your name',s.senderName)}${selectedProduct?input('senderEmail','Sender email',c.sender,'email'):''}${input('businessAddress','Business postal address or qualifying mailbox',s.businessAddress)}</div><p class="quiet">This address appears in your email footer.</p><button type="submit" class="primary">Save sender details</button><p id="sender-save-status" role="status"></p></form><form id="locations-form" class="panel"><h2>Locations</h2>${locationPicker()}<p class="quiet">Your selected locations constrain this workspace. Product search topics follow its approved OpenAI customer profile.</p><button type="submit" class="primary">Save locations</button></form><form id="settings-form" class="panel"><h2>Preferences</h2><details><summary>Customer targeting</summary>${customerFields(s)}</details><label class="checkbox"><input name="researchAutomation" type="checkbox" ${s.researchAutomation!==false?'checked':''}>Automatic discovery and research</label><p class="quiet">These preferences apply only to the selected workspace. Review recipients before sending.</p><details><summary>Offer, portfolio & pricing</summary><label>What you offer<textarea name="offerContext">${esc(s.offerContext)}</textarea></label><label>Portfolio and pricing (optional)<textarea name="portfolio">${esc(s.portfolio)}</textarea></label></details><details><summary>Daily limits & follow-ups</summary><div class="form-grid">${numberFields.map(([key,label,max])=>key==='followupDays'?input(key,label,s.followupDays.join(', ')):input(key,label,s[key],'number',`min="${key==='sendStartHour'?0:1}" max="${max}"`)).join('')}</div><label class="checkbox"><input name="sendWeekends" type="checkbox" ${s.sendWeekends?'checked':''}>Allow weekend sending</label><p class="quiet">Follow-up emails also wait for you to click Send. A reply stops follow-ups.</p></details><details><summary>Budget & search limits</summary><p class="quiet">This is the workspace spending ceiling, not approval for each search. Save it once; research uses the available allowance automatically. A prospect's purchasing budget in Unknowns is unrelated.</p><div class="form-grid">${[['openaiBudget','Workspace OpenAI monthly budget ($)',50],['discoveryResults','Candidates per search (maximum)',10],['discoveryIntervalDays','Days between completed campaigns',30]].map(([key,label,max])=>input(key,label,s[key],'number',`step="${key==='discoveryResults'||key==='discoveryIntervalDays'?1:0.01}" min="${key==='discoveryResults'||key==='discoveryIntervalDays'?1:0.01}" max="${max}"`)).join('')}</div></details><details><summary>Sending service</summary><label class="checkbox"><input name="providerPolicyConfirmed" type="checkbox" ${s.providerPolicyConfirmed?'checked':''}>I checked that my email service permits sending these emails.</label><p class="quiet">This acknowledgement applies to sending emails, not product analysis or prospect research.</p></details><button type="submit" class="primary spaced">Save settings</button></form><details class="panel"><summary>Connections & sending activation</summary>${[['OpenAI research & discovery','openai'],['Gmail','gmail'],['Telegram','telegram']].map(([label,key])=>`<div class="connection"><span>${label}</span>${pill(c[key]?'Configured':'Missing')}</div>`).join('')}<p>Sending from ${esc(c.sender)} · ${c.sendingEnabled?'Activated':'Paused'}</p><p>Only emails you choose to Send leave your Gmail account. Your saved postal address is included in the footer.</p><p>Automatic prospect research: ${c.automationEnabled?'On':'Off'}</p><p class="quiet">OpenAI, Gmail, Telegram, activation switches and notification destinations use the shared Relay connections. Sender identities must be authorized in Gmail.</p><button data-action="check">Check connections</button><div id="connection-results"></div></details><details class="panel"><summary>Notifications</summary><p>Updates go to your configured Telegram chat and ${esc(c.notificationEmail||'notification email')}.</p><button data-action="notify">Send me a status update</button></details>${activity()}<details class="panel"><summary>Import prospects</summary><button data-action="import">Import a business list</button></details>`;}
function backupNotice(){return snapshotMode?`<div class="note warning" role="status">Showing saved records from ${esc(date(snapshotMode.capturedAt))}. You can browse prospects, emails, drafts, dashboard and settings. Changes and sending are paused until the live database is available.</div>`:'';}
function lockSavedControls(){if(!snapshotMode)return;document.querySelectorAll('#content form input,#content form textarea,#content form select,#content form button,#content [data-action],#content [data-retry],#content [name="locationIds"],#modal-content input,#modal-content textarea,#modal-content select,#modal-content button:not([data-open])').forEach(el=>el.disabled=true);}
function render(){if(!data)return;$('#outreach-state').textContent=data.settings.outreachPaused?'Relay paused':'Relay active';$('#outreach-state').classList.toggle('paused',!!data.settings.outreachPaused);$('#outreach-toggle').textContent=data.settings.outreachPaused?'Resume Relay':'Pause Relay';$('#outreach-toggle').disabled=!!snapshotMode;const names={prospects:'Prospects',dashboard:'Dashboard',settings:'Settings',products:'Product research'};$('#breadcrumb').textContent=names[view];$('#pace').textContent=data.settings.dailyNewLimit+' new emails / day';$('#live-status').textContent=snapshotMode?'Saved copy - Read only':data.connections.sendingEnabled?'Gmail connected':'Sending paused';document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));$('#content').innerHTML=workspaceNotice()+({prospects,dashboard,settings:settingsPage,products:productsPage}[view])();renderProductSwitch();lockSavedControls();}
function openModal(html){$('#modal-content').innerHTML=backupNotice()+html;lockSavedControls();if(!$('#modal').open)$('#modal').showModal();}
function leadForm(l){return `<form id="lead-form" data-id="${l.id}"><div class="form-grid">${input('email','Email',l.email||'','email')}${input('contact_name','Contact name',l.contact_name)}<label>Contact permission<select name="eligibility">${['pending','eligible','ineligible'].map(x=>`<option value="${x}" ${l.eligibility===x?'selected':''}>${{pending:'Not recorded',eligible:'Can contact',ineligible:'Do not contact'}[x]}</option>`).join('')}</select><label>Contact basis<textarea name="eligibility_note">${esc(l.eligibility_note)}</textarea></label><label>Email check notes<textarea name="verification_note">${esc(l.verification_note)}</textarea></label></div><label class="checkbox"><input type="checkbox" name="manual" ${l.verification==='manual'?'checked':''}>I reviewed this public business address (delivery unknown).</label><button type="submit">Save contact</button></form>`;}
async function openProspect(id,draftId){detailData=await api('/api/prospects/'+encodeURIComponent(id));const {lead:l,drafts}=detailData;const d=drafts.find(x=>x.id===draftId)||drafts.find(x=>['pending','approved','failed','sending','uncertain'].includes(x.status))||drafts[0];if(d){await draftModal(d.id);return;}modalDraft=null;openModal(`<h2>${esc(l.company)}</h2><p>Research is preparing this business for review.</p>${contactEvidenceHtml(l)}<details><summary>Contact details</summary>${leadForm(l)}</details>`);}
function intelligenceHtml(l){let d={};try{d=JSON.parse(l.dossier||'{}');}catch{}return d.businessSummary?`<p><strong>Business</strong> · ${esc(d.businessSummary)}</p><p><strong>Opportunity hypothesis</strong> · ${esc(d.opportunity)}</p><p><strong>Unknowns</strong> · ${esc((d.unknowns||[]).join('; '))}</p>`:'';}
function contactEvidenceHtml(l){let c={};try{c=JSON.parse(l.contact_evidence||'{}');}catch{}return c.sourceUrl?`<p>Public contact: <a href="${safeLink(c.sourceUrl)}" target="_blank" rel="noopener">Source</a> · ${esc(c.status)} · Delivery unknown</p><p>${esc(c.excerpt||c.reason)}</p>`: '<p class="quiet">Public email source needs review. An email address is not proof of mailbox delivery.</p>';}
function historyHtml(){return (detailData.messages||[]).length?detailData.messages.map(m=>`<details><summary>${m.direction==='outbound'?'Sent':'Received'} · ${date(m.created_at)} · ${esc(m.subject)}</summary><div class="pre">${esc(m.body)}</div></details>`).join(''):'<p>No emails sent or received yet.</p>';}
function sendExplanation(d,l){return `<p class="quiet send-explanation">${d.kind==='followup'&&Date.parse(l.next_followup_at)>Date.now()?'Approval saves your edits and schedules this follow-up for its due date.':'Send saves your edits, confirms this recipient can be contacted, and sends this email through Gmail.'}</p>`;}
function followupOrdinal(d,l){if(d.status!=='sent')return Math.min(3,Number(l.followup_count||0)+1);const sent=detailData.drafts.filter(x=>x.kind==='followup'&&x.status==='sent').sort((a,b)=>a.created_at.localeCompare(b.created_at)||a.id.localeCompare(b.id));return sent.findIndex(x=>x.id===d.id)+1;}
async function draftModal(id){const d=detailData?.drafts.find(x=>x.id===id),l=detailData?.lead;if(!d||!l)return;modalDraft=id;const editable=!snapshotMode&&['pending','failed'].includes(d.status),issues=prospectIssues(d);const status={pending:'Pending send',approved:'Scheduled',failed:'Send failed',uncertain:'Check delivery',sending:'Sending',sent:'Sent',rejected:'Not sent',cancelled:'Not sent'}[d.status]||d.status;
 openModal(`<div class="simple-review"><h2>${esc(l.company)}</h2><p>To: ${esc(l.email||'Email not found')} · ${esc(status)}</p>${d.kind==='followup'?`<p class="note">Follow-up ${followupOrdinal(d,l)} of 3 - ${d.status==='sent'?'Sent '+date(d.updated_at):'Due '+date(l.next_followup_at||d.send_after)}. ${Date.parse(l.next_followup_at||d.send_after)>Date.now()?'Approval schedules it for the due date; it will not send early.':'Awaiting your Send approval.'}</p>`:''}${editable?sendingNotice():''}${d.error?`<p class="note error">${esc(d.error)}</p>`:''}${issues.length&&editable?`<p class="note warning">${esc(issues[0])}</p>`:''}<form id="draft-form" data-id="${id}" data-version="${d.version}"><label>Subject<input name="subject" value="${esc(d.subject)}" ${editable?'':'disabled'}></label><label>Email<textarea name="body" rows="11" ${editable?'':'disabled'}>${esc(draftMessage(d))}</textarea></label>${editable?'<button type="submit">Save changes</button>':''}</form><details><summary>Sender footer</summary><div id="email-preview" class="pre">Loading…</div></details><details><summary>Research & contact details</summary><p>${esc(emailCheck(l))}</p><p>${esc(l.verification_note)}</p>${contactEvidenceHtml(l)}${intelligenceHtml(l)}<p>${esc(d.rationale)}</p>${JSON.parse(d.evidence).map(x=>`<p>${esc(x.observation)} <a href="${safeLink(x.url)}" target="_blank" rel="noopener">Source</a></p>`).join('')}${JSON.parse(d.warnings).map(w=>`<p>${esc(w)}</p>`).join('')}<details><summary>Edit contact</summary>${leadForm(l)}</details>${editable?`<button data-rewrite="${id}">Improve this email</button>`:''}<button class="danger" data-suppress="${l.id}">Stop contacting this business</button></details><details><summary>Email history</summary>${historyHtml()}</details>${editable?sendExplanation(d,l):''}<div class="modal-actions">${editable?`<button data-reject="${id}">Discard email</button><button class="primary" data-send="${id}" ${!data.settings.outreachPaused&&data.connections.sendingEnabled&&data.settings.businessAddress.trim()&&!issues.length?'':'disabled'}>${d.kind==='followup'&&Date.parse(l.next_followup_at)>Date.now()?'Approve follow-up':'Send'}</button>`:''}${['sending','uncertain'].includes(d.status)?`<button data-reconcile="${id}">Check delivery</button>`:''}${d.status==='approved'?'<p>Scheduled. It will send automatically; no second approval needed.</p>':''}</div></div>`);
 try{const p=await api(`/api/drafts/${id}/preview`);if(modalDraft===id&&$('#email-preview')){const message=draftMessage(d);$('#email-preview').textContent=p.body.startsWith(message)?p.body.slice(message.length).trim():p.body;}}catch(e){toast(e.message);}
}
function importModal(){modalDraft=null;openModal(`<h2>Import prospects</h2><form id="import-form"><label>Business records (JSON)<textarea name="records" rows="12" required></textarea></label><button type="submit">Import</button></form>`);}
async function saveEmail(d){const form=$('#draft-form');const subject=form.elements.namedItem('subject').value,body=form.elements.namedItem('body').value;if(subject===d.subject&&body===draftMessage(d))return d.version;await api(`/api/drafts/${d.id}/edit`,{version:d.version,subject,body,artifact:''});d.subject=subject;d.body=body;d.artifact='';d.version++;form.dataset.version=d.version;return d.version;}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;try{
 if(b.hasAttribute('data-billing-updated')){if(confirm('Confirm that billing is funded for the OpenAI project used by Relay. This clears the billing stop; paused workspaces stay paused.'))await action('/api/openai/control',{billingUpdated:true});return;}
 if(b.id==='outreach-toggle'){await action('/api/outreach/control',{paused:!data.settings.outreachPaused});return;}
 if(b.hasAttribute('data-discovery-control')){await action('/api/discovery/control',{paused:!!(data.settings.prospectingPaused||data.settings.discoveryPaused)?false:true});return;}
 if(b.id==='notification-toggle'){$('#notification-panel').hidden=!$('#notification-panel').hidden;b.setAttribute('aria-expanded',String(!$('#notification-panel').hidden));if(!$('#notification-panel').hidden)await refreshNotifications();return;}
 if(b.id==='notifications-read-all'){notificationData=await api('/api/notifications/read',{all:true});renderNotifications();return;}
 if(b.dataset.notification){const item=notificationData.items.find(n=>n.id===b.dataset.notification);if(!item)return;notificationData=await api('/api/notifications/read',{id:item.id});renderNotifications();$('#notification-panel').hidden=true;$('#notification-toggle').setAttribute('aria-expanded','false');await switchProduct(item.product_id||'');if((item.product_id||'')!==selectedProduct){toast('This product workspace is archived.');return;}await openProspect(item.lead_id,item.draft_id);if(item.kind!=='followup_ready'){const summary=[...$('#modal-content').querySelectorAll('summary')].find(s=>s.textContent==='Email history');if(summary)summary.parentElement.open=true;}return;}
 if(b.dataset.productNew!==undefined){productForm();return;}
 if(b.dataset.productEdit){productForm((await api('/api/products/'+b.dataset.productEdit)).product);return;}
 if(b.dataset.productOpen){await switchProduct(b.dataset.productOpen,'prospects');return;}
 if(b.dataset.productResearch){await switchProduct(b.dataset.productResearch,'products');return;}
 if(b.dataset.productAnalyze){await api('/api/products/'+b.dataset.productAnalyze+'/analyze',{confirmPaidRetry:true});await load();toast('OpenAI research queued; target approval is required before prospect searches.');return;}
 if(b.dataset.productAdvance){await api('/api/products/'+b.dataset.productAdvance+'/run',{});await load();return;}
 if(b.dataset.productApprove){await api('/api/products/'+b.dataset.productApprove+'/approve',{revision:Number(b.dataset.revision),profileReviewed:true});await load();toast('Customer profile approved. Choose Resume prospects when ready; this product remains paused.');return;}
 if(b.dataset.productPause){const p=products.find(p=>p.id===b.dataset.productPause);await api('/api/products/'+p.id+'/prospecting',{paused:!p.prospecting_paused});await load();return;}
 if(b.dataset.productSender){const r=await api('/api/products/'+b.dataset.productSender+'/sender',{});toast(r.accepted?'Sender is authorized in the connected Gmail mailbox.':r.message);return;}
 if(b.hasAttribute('data-reload')){await load();return;}
 if(workspaceUnavailable&&(b.dataset.view||b.dataset.go)){await load();return;}
 if(b.dataset.view||b.dataset.go){view=b.dataset.view||b.dataset.go;filter='';statusFilter='all';if($('#modal').open)$('#modal').close();if(view==='products'&&selectedProduct)productDetailData=await api('/api/products/'+selectedProduct);await fetchPage();render();return;}
 if(b.dataset.group){dashboardGroup=b.dataset.group;await fetchPage();render();return;}
 if(b.dataset.page!==undefined){await fetchPage(Number(b.dataset.page));render();return;}
 if(b.dataset.open){await openProspect(b.dataset.open,b.dataset.email);return;}
 if(b.id==='close-modal'){$('#modal').close();modalDraft=null;return;}
 if(b.id==='refresh'){await load();return;}
 if(b.id==='logout'){await api('/api/logout',{});data=null;notificationData={items:[],unread:0};renderNotifications();$('#notification-panel').hidden=true;workspaceUnavailable=false,snapshotMode=null,lastSavedRefresh=0;$('#app').hidden=true;$('#login').hidden=false;return;}
 if(b.dataset.action==='import'){importModal();return;}
 if(b.dataset.action==='discover'){
  if(selectedProduct&&!profileReady()){
   view='products';await load();
   toast(currentProduct()?.state==='analyzing'?'Your updated targeting is being analyzed. Approve the new profile when it is ready, then Find prospects skips the automatic wait.':'Review and approve your updated targeting here. Find prospects then skips the automatic campaign wait.');return;
  }
  if(data.settings.outreachPaused){toast('Relay is paused. Resume Relay at the top before requesting a manual search.');return;}
  if(data.settings.prospectingPaused){openModal('<h2>Prospecting is paused</h2><p>Resume this workspace to allow research and drafting. This will also enable its automatic prospecting schedule.</p><button class="primary" data-resume-and-find>Resume prospecting &amp; find prospects</button>');return;}
 }
 if(b.hasAttribute('data-resume-and-find')){b.disabled=true;const locations=await saveLocations();if(locations.profileChanged){$('#modal').close();view='products';await load();toast(locations.message);return;}await api('/api/discovery/control',{paused:false});$('#modal').close();await action('/api/discover',{},'Manual prospect search queued');return;}
 b.disabled=true;
 if(b.dataset.send){const d=detailData.drafts.find(x=>x.id===b.dataset.send);b.textContent='Sending…';const version=await saveEmail(d);const result=await api(`/api/drafts/${d.id}/approve`,{version,evidenceReviewed:true,contactReviewed:true});toast(result.message);await load();if(result.status==='sent'){$('#modal').close();modalDraft=null;}else await openProspect(d.lead_id,d.id);}
 if(b.dataset.reject){const d=detailData.drafts.find(x=>x.id===b.dataset.reject);await action(`/api/drafts/${d.id}/reject`,{version:d.version},'Email discarded');$('#modal').close();modalDraft=null;}
 if(b.dataset.rewrite){const d=detailData.drafts.find(x=>x.id===b.dataset.rewrite);await action(`/api/drafts/${d.id}/rewrite`,{version:d.version},'Improving this email in the background.');$('#modal').close();modalDraft=null;}
 if(b.dataset.suppress){await action(`/api/leads/${b.dataset.suppress}/suppress`,{},'Contact stopped');$('#modal').close();}
 if(b.dataset.reconcile){await action(`/api/drafts/${b.dataset.reconcile}/reconcile`,{},'Delivery checked');await openProspect(detailData.lead.id,b.dataset.reconcile);}
 if(b.dataset.action==='discover'){b.textContent='Finding prospects…';const locations=await saveLocations();if(locations.profileChanged){toast(locations.message);await load();return;}await action('/api/discover',{},'Prospect search started.');}
 if(b.dataset.action==='tick')await action('/api/tick',{},'Background tasks completed');
 if(b.dataset.action==='notify')await action('/api/notify',{},'Status update requested');
 if(b.dataset.action==='check'){const result=await api('/api/connections/check',{});$('#connection-results').innerHTML=Object.entries(result).map(([k,v])=>`<p>${esc(k)}: ${esc(v)}</p>`).join('');}
 if(b.dataset.retry)await action(`/api/jobs/${b.dataset.retry}/retry`,{confirmPaidRetry:true},'Retry queued');
 }catch(error){toast(error.message);}finally{b.disabled=false;if(b.dataset.send)b.textContent='Send';if(b.dataset.action==='discover')b.textContent='Find prospects';}
});
document.addEventListener('input',e=>{if(e.target.id==='location-search'){const q=e.target.value.toLowerCase();document.querySelectorAll('[data-location-label]').forEach(x=>x.hidden=!x.dataset.locationLabel.includes(q));return;}if(e.target.id==='search'){filter=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{try{if(await fetchPage()){const cursor=$('#search')?.selectionStart;render();$('#search')?.focus();$('#search')?.setSelectionRange(cursor,cursor);}}catch(err){toast(err.message);}},220);}});
document.addEventListener('change',async e=>{if(e.target.name==='locationIds'){if(e.target.checked){document.querySelectorAll('[name="locationIds"]').forEach(x=>{if(e.target.value==='worldwide'&&x!==e.target)x.checked=false;else if(e.target.value!=='worldwide'&&x.value==='worldwide')x.checked=false;});}locationSelection=chosenLocations();$('#location-summary').textContent=locationSelection.includes('worldwide')?'Worldwide - automatic':locationSelection.length+' locations selected';return;}if(e.target.id==='status-filter'){statusFilter=e.target.value;try{await fetchPage();render();}catch(err){toast(err.message);}}});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,button=form.querySelector('button[type=submit]');if(button)button.disabled=true;try{
 if(form.id==='product-form'){const f=new FormData(form),payload={name:String(f.get('name')),website:String(f.get('website')),description:String(f.get('description')),remarks:String(f.get('remarks')),sender_email:String(f.get('sender_email')),customerTypes:f.getAll('customerTypes'),customerDescription:String(f.get('customerDescription')),customerComments:String(f.get('customerComments')),revision:Number(form.dataset.revision)};const files=[...form.querySelector('[name=screenshots]').files];if(files.length){if(files.length>3||files.some(f=>f.size>512000))throw new Error('Choose up to three screenshots, each at most 500 KB');payload.images=await Promise.all(files.map(async file=>({name:file.name,data:await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file);})})));}else if(f.has('clearImages'))payload.images=[];const result=await api('/api/products'+(form.dataset.id?'/'+form.dataset.id:''),payload);$('#modal').close();await switchProduct(result.product.id,'products');toast('Product saved. Run OpenAI research, then review its proposed customer profile.');return;}
 if(form.id==='login-form'){await api('/api/login',{password:$('#password').value});$('#password').value='';$('#login-error').textContent='';view='prospects';await load();}
 if(form.id==='draft-form'){const d=detailData.drafts.find(x=>x.id===form.dataset.id);await saveEmail(d);toast('Email saved');await openProspect(d.lead_id,d.id);await load();}
 if(form.id==='lead-form'){const f=new FormData(form);await action(`/api/leads/${form.dataset.id}/update`,{...Object.fromEntries(f),verification:f.has('manual')?'manual':'unchanged'},'Contact saved');await openProspect(form.dataset.id,modalDraft);}
 if(form.id==='import-form'){const r=await action('/api/import',{leads:JSON.parse(form.elements.namedItem('records').value)});toast(`${r.added} added, ${r.duplicates} duplicates, ${r.errors.length} errors`);if(!r.errors.length)$('#modal').close();}
 if(form.id==='sender-form'){const f=new FormData(form);await action('/api/settings/sender',{senderName:String(f.get('senderName')),businessAddress:String(f.get('businessAddress')),...(selectedProduct?{senderEmail:String(f.get('senderEmail'))}:{})},'Sender details saved');$('#sender-save-status').textContent='Saved. Your email footer is updated.';}
 if(form.id==='locations-form'){await saveLocations();toast('Locations saved. Rotation runs automatically.');await load();}
 if(form.id==='settings-form'){const f=new FormData(form),s={...data.settings};for(const k of ['dailyLeadLimit','dailyNewLimit','dailyTotalLimit','dailyResearchLimit','openaiBudget','discoveryResults','discoveryIntervalDays','sendStartHour','sendEndHour'])s[k]=Number(f.get(k));s.researchAutomation=f.has('researchAutomation');s.customerTypes=f.getAll('customerTypes');for(const k of ['offerContext','portfolio','customerDescription','customerComments'])s[k]=String(f.get(k));s.followupDays=String(f.get('followupDays')).split(',').map(x=>x.trim()).filter(Boolean).map(Number);s.sendWeekends=f.has('sendWeekends');s.providerPolicyConfirmed=f.has('providerPolicyConfirmed');await action('/api/settings/preferences',s,'Preferences saved');}
 }catch(err){if(form.id==='login-form')$('#login-error').textContent=err.message;else toast(err.message);}finally{if(button)button.disabled=false;}
});
load().catch(e=>{if(!e.message.includes('Sign in'))$('#login-error').textContent=e.message;});
let refreshing=false;
setInterval(()=>{if(data&&!document.hidden)refreshNotifications();},30000);
setInterval(async()=>{if(refreshing||!data||(snapshotMode&&Date.now()-lastSavedRefresh<300000)||document.hidden||$('#modal').open||document.querySelector('.location-picker[open]')||view==='settings'||document.activeElement?.matches('input,textarea,select'))return;refreshing=true;try{await load();}catch{}finally{refreshing=false;}},60000);


async function switchProduct(id,nextView='prospects'){selectedProduct=id||'';sessionStorage.setItem('relay-product',selectedProduct);snapshotMode=null;locationSelection=null;detailData=null;modalDraft=null;pageData.offset=0;view=nextView;data=null;$('#content').innerHTML=empty('Loading workspace?','');if($('#modal').open)$('#modal').close();await load();}
function renderProductSwitch(){
 const select=$('#product-switch');if(select)select.innerHTML='<option value="">Existing outreach</option>'+products.map(p=>`<option value="${esc(p.id)}" ${p.id===selectedProduct?'selected':''}>${esc(p.name)}</option>`).join('');
 if(select)select.value=selectedProduct;
 if(selectedProduct){const p=products.find(p=>p.id===selectedProduct);$('#breadcrumb').textContent=(p?.name||'Product')+' / '+({products:'Research',prospects:'Prospects',dashboard:'Dashboard',settings:'Settings'}[view]);if(view==='prospects'&&!profileReady(p)){for(const b of document.querySelectorAll('[data-discovery-control]'))b.disabled=true;}}
}
function productsPage(){
 const cards=products.map(p=>`<article class="panel product-card"><h2>${esc(p.name)}</h2><p>${esc(p.website)}</p><p>${pill(p.state.replaceAll('_',' '))} ${pill(p.prospecting_paused?'Prospecting paused':'Prospecting enabled')}</p><p class="quiet">Separate limits and budget in this workspace Settings</p><div class="actions"><button data-product-research="${p.id}">Research & details</button><button data-product-open="${p.id}">Prospects</button><button data-product-pause="${p.id}" ${!profileReady(p)?'disabled':''}>${p.prospecting_paused?'Resume prospects':'Pause prospects'}</button></div></article>`).join('');
 let detail='';const x=productDetailData;if(selectedProduct&&x?.product?.id===selectedProduct){const p=x.product,a=x.analysis||{};
 detail=`<section class="panel product-research"><h2>${esc(p.name)} research</h2><p>${esc(p.description)}</p><p><strong>Your remarks</strong><br>${esc(p.remarks||'None added')}</p><p>Sender: ${esc(p.sender_email)} <button data-product-sender="${p.id}">Check sender</button></p><p class="quiet">The sender must be an authorized send-as address in your connected Gmail mailbox.</p><div class="product-images">${(x.images||[]).map(i=>`<img src="${i.data}" alt="${esc(i.name)}">`).join('')}</div><p>${pill(p.state.replaceAll('_',' '))} &middot; Revision ${p.revision} &middot; OpenAI committed this month: ${money(x.budget?.committed)}</p><div class="actions"><button data-product-edit="${p.id}">Edit product & remarks</button><button data-product-pause="${p.id}" ${!profileReady(p)?'disabled':''}>${p.prospecting_paused?'Resume prospects':'Pause prospects'}</button><span>${p.prospecting_paused?'Prospecting paused':'Prospecting enabled'}</span>${['draft','failed','uncertain','paused_provider'].includes(p.state)?`<button class="primary" data-product-analyze="${p.id}" ${p.state==='uncertain'?'disabled':''}>Research product with OpenAI</button>`:''}${p.state==='analyzing'?`<button data-product-advance="${p.id}">Continue research now</button><span>OpenAI research is queued; it also progresses automatically.</span>`:''}</div>${a.productSummary?`<hr><h3>OpenAI product understanding</h3><p>${esc(a.productSummary)}</p><p>${esc(a.valueProposition)}</p><h3>Proposed target customers</h3>${listHtml(a.targetCustomers)}<p><strong>Buying roles:</strong> ${esc((a.buyingRoles||[]).join(', '))}</p><p>${esc(a.targetingRationale)}</p><h3>Qualification criteria</h3>${listHtml(a.qualificationCriteria)}<h3>Exclusions</h3>${listHtml(a.exclusions)}<h3>Your remarks applied</h3>${listHtml(a.remarksApplied)}<p><strong>Email guidance:</strong> ${esc(a.emailGuidance)}</p><h3>Unknowns</h3><p class="quiet">These are unverified facts, not automatic blockers. Buyer budget, authority, file suitability and intent may stay unknown until a prospect provides evidence or answers. Buyer budget is separate from your Relay research spending cap.</p>${listHtml(a.unknowns)}<button data-product-edit="${p.id}">Add answers or corrections</button><p class="quiet">Put verified product facts in Product description or Additional remarks. Use Settings, Customer targeting for buyer preferences. Saving changes requires a new analysis and profile approval; nothing resumes automatically.</p><h3>Proposed search scopes</h3>${listHtml((a.campaigns||[]).map(c=>c.query+' - '+c.location))}<details><summary>Sources (${(a.sources||[]).length})</summary>${(a.sources||[]).map(v=>`<p><a href="${safeLink(v.url)}" target="_blank" rel="noopener">${esc(v.observation||v.url)}</a></p>`).join('')}</details>${p.state==='target_review'?`<div class="profile-review"><h3>Check before approving</h3><ul><li>Product facts and exclusions match what you actually sell; check the source links.</li><li>Customer types and buying roles match people who own the workflow.</li><li>Qualification criteria require public evidence, with assumptions kept conditional.</li><li>Search locations, owner comments and email guidance match your intended outreach.</li></ul><p>Unknowns do not have to be empty. Approve the proposed targeting only when these checks are correct.</p><button class="primary" data-product-approve="${p.id}" data-revision="${p.revision}">Approve target profile</button><p class="quiet">Prospecting stays paused until you choose Resume prospects for this product. Every email needs your separate Send approval.</p></div>`:''}`:''}</section>`;
 }
 return title('Products','Configure a product, let OpenAI research it, then approve its target-customer profile.', '<button class="primary" data-product-new>Add product</button>')+'<p class="quiet">New products start with prospecting paused. Product setup and analysis work independently. Separate prospects, conversations, senders and allowances per product. Global opt-outs are respected across products.</p>'+detail+'<div class="product-grid">'+(cards||empty('Add your first product','Provide its website, description and optional screenshots.'))+'</div>';
}
function listHtml(items){return (items||[]).length?'<ul>'+items.map(v=>'<li>'+esc(v)+'</li>').join('')+'</ul>':'<p class="quiet">None recorded</p>';}
function productForm(p){openModal(`<h2>${p?'Edit':'Add'} product</h2><form id="product-form" data-id="${esc(p?.id||'')}" data-revision="${p?.revision||0}"><label>Product name<input name="name" value="${esc(p?.name||'')}" required maxlength="120"></label><label>Product website<input name="website" type="url" value="${esc(p?.website||'')}" required></label><label>Product description<textarea name="description" rows="5" maxlength="12000" required>${esc(p?.description||'')}</textarea></label><label>Additional remarks, prospect instructions & known facts<textarea name="remarks" rows="5" maxlength="12000" placeholder="What customers to find or exclude, geography, product points and email instructions">${esc(p?.remarks||'')}</textarea></label><details open><summary>Customer targeting</summary>${customerFields(p||{})}</details><label>Sender email<input name="sender_email" type="email" value="${esc(p?.sender_email||data.connections.sender||'')}" required></label><label>Screenshots (optional)<input name="screenshots" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><p class="quiet">Up to three screenshots, 500 KB each. OpenAI analyzes them along with your website and remarks. Research costs count toward this product's $50 monthly cap.</p>${p?'<label class="checkbox"><input name="clearImages" type="checkbox">Remove saved screenshots if no replacements are selected</label><p class="quiet">Editing requires a new target-profile approval. Existing draft text is preserved for review; sent history is unchanged.</p>':''}<button type="submit" class="primary">Save product</button></form>`);}
document.addEventListener('change',async e=>{if(e.target.id==='product-switch'){try{await switchProduct(e.target.value,view);}catch(error){toast(error.message);}}});
